package com.pricetrack.exchange.custody.direct;
import com.pricetrack.exchange.custody.abi.CAbiEventModels.Transfer;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.pricetrack.exchange.custody.abi.*;
import com.pricetrack.exchange.custody.abi.CAbiEventModels.*;
import com.pricetrack.exchange.custody.abi.CAbiModels.*;
import com.pricetrack.exchange.custody.authorization.CConsentModels;
import com.pricetrack.exchange.custody.proof.CEip712Verifier;
import com.pricetrack.exchange.custody.runtime.*;
import java.math.BigInteger;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.web3j.crypto.Hash;
import static org.junit.jupiter.api.Assertions.*;

/** Actual fixed Reader identity checks plus Mock RPC transaction/Receipt evidence; not live RPC or finality. */
public class CDirectReceiptReaderTest {
    static final JsonNodeFactory J=JsonNodeFactory.instance;static final BigInteger ZERO=BigInteger.ZERO,ONE=BigInteger.ONE;
    static String a(int n){return CDirectServiceTest.a(n);}static String h(int n){return CDirectServiceTest.h(n);}static BigInteger b(long n){return BigInteger.valueOf(n);}static String q(BigInteger n){return "0x"+n.toString(16);}
    static String word(BigInteger n){return "0x"+String.format("%064x",n);}static String aw(String a){return "0x"+"0".repeat(24)+a.substring(2);}static String sel(String sig){return Hash.sha3String(sig).substring(0,10);}
    /** IERC-5267 eip712Domain() returns an ABI tuple, NOT the bytes32 EIP-712 domain separator. */
    static String domain(String name,BigInteger chain,String target){return "0x"+org.web3j.abi.FunctionEncoder.encodeConstructor(List.of(
        new org.web3j.abi.datatypes.generated.Bytes1(new byte[]{0x0f}),new org.web3j.abi.datatypes.Utf8String(name),new org.web3j.abi.datatypes.Utf8String("1"),
        new org.web3j.abi.datatypes.generated.Uint256(chain),new org.web3j.abi.datatypes.Address(target),new org.web3j.abi.datatypes.generated.Bytes32(new byte[32]),
        new org.web3j.abi.datatypes.DynamicArray<org.web3j.abi.datatypes.generated.Uint256>(org.web3j.abi.datatypes.generated.Uint256.class,List.of())));}
    static class Fixture implements CReadRpc {
        final String owner=a(20),txHash=h(200),blockHash=h(100),parent=h(99);final CCustodyIdentity id;
        final Map<String,String> getters=new HashMap<>();ObjectNode tx,receipt;ArrayNode logs;CDirectModels.ExecutionView expected;
        boolean txAbsent,receiptAbsent,reorg,receiptChanges;int numberedHeaders,receiptReads,calls;
        Fixture(){var c=CDirectServiceTest.identity();id=new CCustodyIdentity(c.chainId(),c.genesisHash(),new CCustodyIdentity.Contract(c.token().address(),Hash.sha3("0x6001")),new CCustodyIdentity.Contract(c.controller().address(),Hash.sha3("0x6002")),new CCustodyIdentity.Contract(c.rules().address(),Hash.sha3("0x6003")),new CCustodyIdentity.Contract(c.vault().address(),Hash.sha3("0x6004")),c.relayer(),c.oracle(),c.pauseAdmin(),c.symbolHash(),c.policyHash(),c.origin());
            put(id.controller().address(),"rules()",aw(id.rules().address()));put(id.controller().address(),"vault()",aw(id.vault().address()));put(id.controller().address(),"relayer()",aw(id.relayer()));put(id.controller().address(),"pauseAdmin()",aw(id.pauseAdmin()));put(id.vault().address(),"asset()",aw(id.token().address()));put(id.vault().address(),"controller()",aw(id.controller().address()));put(id.rules().address(),"executor()",aw(id.controller().address()));put(id.rules().address(),"priceSigner()",aw(id.oracle()));put(id.rules().address(),"supportedSymbolHash()",id.symbolHash());put(id.rules().address(),"policyHash()",id.policyHash());put(id.token().address(),"totalSupply()",word(CCustodyIdentity.SUPPLY));put(id.token().address(),"decimals()",word(b(18)));put(id.controller().address(),"eip712Domain()",domain(CCustodyIdentity.USER_DOMAIN,id.chainId(),id.controller().address()));put(id.rules().address(),"eip712Domain()",domain(CCustodyIdentity.PRICE_DOMAIN,id.chainId(),id.rules().address()));
            funding("APPROVE");
        }
        void put(String target,String sig,String data){getters.put(target+sel(sig),data);}
        CDirectReceiptReader reader(){return new CDirectReceiptReader(new CCustodyRpcReader(id,this,Clock.fixed(CDirectServiceTest.NOW,ZoneOffset.UTC)),this);}
        void base(String target,String input){tx=J.objectNode().put("hash",txHash).put("from",owner).put("to",target).put("value","0x0").put("input",input).put("blockNumber","0x64").put("blockHash",blockHash).put("transactionIndex","0x0");receipt=J.objectNode().put("transactionHash",txHash).put("from",owner).put("to",target).put("blockNumber","0x64").put("blockHash",blockHash).put("transactionIndex","0x0").put("status","0x1");logs=receipt.putArray("logs");expected=null;}
        void event(String emitter,Event event){var encoded=new CAbiEventCodec().encode(emitter,event);var log=logs.addObject().put("transactionHash",txHash).put("blockHash",blockHash).put("blockNumber","0x64").put("transactionIndex","0x0").put("logIndex","0x"+Integer.toHexString(logs.size()-1)).put("removed",false).put("address",emitter).put("data",encoded.data());var topics=log.putArray("topics");encoded.topics().forEach(topics::add);}
        void funding(String kind){BigInteger amount=b(1000);Call call=kind.equals("APPROVE")?new Approve(id.vault().address(),amount):new VaultAmount(kind.equals("DEPOSIT")?VaultAction.DEPOSIT:VaultAction.WITHDRAW,amount);base(kind.equals("APPROVE")?id.token().address():id.vault().address(),new CAbiCodec().encode(call));if(kind.equals("APPROVE"))event(id.token().address(),new Approval(owner,id.vault().address(),amount));else if(kind.equals("DEPOSIT")){event(id.token().address(),new Transfer(owner,id.vault().address(),amount));event(id.vault().address(),new Deposited(owner,amount));}else{event(id.token().address(),new Transfer(id.vault().address(),owner,amount));event(id.vault().address(),new Withdrawn(owner,amount));}}
        void direct(boolean close,BigInteger paid){
            BigInteger action=close?b(4):ZERO,price=CDirectServiceTest.E8.multiply(b(close?105:100)),entry=CDirectServiceTest.E8.multiply(b(100)),observed=b(CDirectServiceTest.NOW.getEpochSecond());
            Intent i=new Intent(owner,id.relayer(),h(20),h(21),CConsentModels.accountRef(owner,id.symbolHash()),id.symbolHash(),action,close?ONE:ZERO,ZERO,ZERO,b(10),close?entry:ZERO,close?b(1000):ZERO,b(1000),CDirectServiceTest.E8.multiply(b(90)),CDirectServiceTest.E8.multiply(b(110)),b(100),b(100),ZERO,observed,observed.add(b(120)),id.policyHash());
            Report r=new Report(i.operationId(),i.positionId(),i.accountRef(),i.symbolHash(),action,i.expectedVersion(),ZERO,ZERO,b(10),b(100),entry,i.collateralBefore(),b(1000),price,observed,observed.add(b(30)),id.policyHash(),id.controller().address());
            var crypto=new CEip712Verifier();var stored=new CDirectModels.Execution(i,r,CDirectServiceTest.sign(r),crypto.reportDigest(r,id.chainId(),id.rules().address()),new com.pricetrack.exchange.futures.runtime.FuturesMarketGate.Mark(price,CDirectServiceTest.NOW,"SIMULATED",1L));String data=new CAbiCodec().encode(new Direct(r,stored.priceSignature(),i));base(id.controller().address(),data);expected=CDirectModels.execution(id,stored,data);
            BigInteger gain=close?b(500):ZERO;event(id.rules().address(),new OperationApplied(i.operationId(),i.positionId(),action,i.expectedVersion().add(ONE),price,b(1000),gain,close?gain:ZERO,ZERO,ZERO,ZERO));event(id.rules().address(),new FuturesReportConsumed(i.operationId(),observed,observed.add(b(30))));
            if(!close)event(id.vault().address(),new CollateralLocked(i.operationId(),i.positionId(),owner,b(1000),b(1000)));
            else{BigInteger unpaid=gain.subtract(paid),claim=unpaid.signum()>0?ONE:ZERO;if(unpaid.signum()>0)event(id.vault().address(),new ProfitClaimCreated(claim,owner,i.positionId(),i.operationId(),unpaid));event(id.vault().address(),new PositionSettled(i.operationId(),i.positionId(),owner,b(1000),gain,ZERO,paid,claim));}
            event(id.controller().address(),new CUserIntentExecuted(i.operationId(),i.positionId(),owner,crypto.intentDigest(i,id.chainId(),id.controller().address()),stored.reportDigest(),action,ZERO,true));
        }
        public JsonNode request(String method,List<Object> params,long timeout){calls++;assertTrue(timeout>0&&timeout<=3000);
            if(method.equals("eth_chainId"))return TextNode.valueOf("0x7a69");
            if(method.equals("eth_getTransactionByHash"))return txAbsent?NullNode.instance:tx.deepCopy();
            if(method.equals("eth_getTransactionReceipt")){receiptReads++;if(receiptAbsent)return NullNode.instance;var result=receipt.deepCopy();if(receiptChanges&&receiptReads>1)result.put("status","0x0");return result;}
            if(method.equals("eth_getBlockByNumber")){String number=(String)params.get(0);if(number.equals("0x0"))return J.objectNode().put("hash",id.genesisHash()).put("number","0x0");boolean numbered=!number.equals("latest");if(numbered)numberedHeaders++;var head=J.objectNode().put("hash",reorg&&numberedHeaders>=3?h(999):blockHash).put("number","0x64").put("parentHash",parent).put("timestamp",q(b(CDirectServiceTest.NOW.getEpochSecond())));head.putArray("transactions").add(txHash);return head;}
            assertEquals(Map.of("blockHash",blockHash,"requireCanonical",true),params.get(1));
            if(method.equals("eth_getCode")){String target=(String)params.get(0);return TextNode.valueOf(target.equals(id.token().address())?"0x6001":target.equals(id.controller().address())?"0x6002":target.equals(id.rules().address())?"0x6003":"0x6004");}
            assertEquals("eth_call",method);@SuppressWarnings("unchecked")Map<String,String> input=(Map<String,String>)params.get(0);String value=getters.get(input.get("to")+input.get("data").substring(0,10));assertNotNull(value,"Unexpected fixed identity selector");return TextNode.valueOf(value);
        }
    }
    static String reject(Fixture f){return assertThrows(CCustodyFailure.class,()->f.reader().inspect(f.owner,f.txHash,f.expected)).code();}
    @Test void approvalDepositAndWithdrawalVerifyExactOwnedEvents(){for(String kind:List.of("APPROVE","DEPOSIT","WITHDRAW")){var f=new Fixture();f.funding(kind);var out=f.reader().inspect(f.owner,f.txHash,null);assertEquals("CONFIRMED",out.get("status"));assertEquals(kind,out.get("kind"));assertEquals(false,out.get("completeCoverage"));assertEquals(CDirectReceiptReader.SCOPE,out.get("scope"));assertTrue(f.calls>40);}}
    @Test void directOpenAndCloseUseStoredCalldataAndCanonicalLinkedEvents(){var open=new Fixture();open.direct(false,ZERO);var out=open.reader().inspect(open.owner,open.txHash,open.expected);assertEquals("OPEN",out.get("kind"));assertEquals("4",out.get("verifiedEvents"));var close=new Fixture();close.direct(true,b(500));var done=close.reader().inspect(close.owner,close.txHash,close.expected);assertEquals("CLOSE",done.get("kind"));assertEquals("500",done.get("realizedPnl"));assertEquals("500",done.get("paidProfit"));assertEquals("0",done.get("unpaidProfit"));}
    @Test void partialProfitIsClaimNotPaidOrFreeGuarantee(){var f=new Fixture();f.direct(true,b(100));var out=f.reader().inspect(f.owner,f.txHash,f.expected);assertEquals("500",out.get("realizedPnl"));assertEquals("100",out.get("paidProfit"));assertEquals("400",out.get("unpaidProfit"));assertEquals("5",out.get("verifiedEvents"));assertFalse(out.containsKey("freeBalance"));assertFalse(out.containsKey("solvent"));}
    @Test void absentAndUnconfirmedTransactionsStayPending(){var absent=new Fixture();absent.txAbsent=true;absent.receiptAbsent=true;assertEquals("PENDING",absent.reader().inspect(absent.owner,absent.txHash,null).get("status"));var pending=new Fixture();pending.receiptAbsent=true;assertEquals("PENDING",pending.reader().inspect(pending.owner,pending.txHash,null).get("status"));var contradictory=new Fixture();contradictory.txAbsent=true;assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(contradictory));}
    @Test void canonicalRevertRequiresNoEventsAndIsNotPending(){var f=new Fixture();f.receipt.put("status","0x0");f.logs.removeAll();assertEquals("REVERTED",f.reader().inspect(f.owner,f.txHash,null).get("status"));var bad=new Fixture();bad.receipt.put("status","0x0");assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(bad));}
    @Test void wrongOwnerTargetValueAndApprovalSpenderAreRejected(){for(String field:List.of("from","to","value","spender")){var f=new Fixture();if(field.equals("from"))f.tx.put("from",a(88));if(field.equals("to"))f.tx.put("to",a(88));if(field.equals("value"))f.tx.put("value","0x1");if(field.equals("spender"))f.tx.put("input",new CAbiCodec().encode(new Approve(a(88),b(1000))));assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(f));}}
    @Test void logDuplicatesRemovedForeignEmitterAndMalformedAbiFailClosed(){for(String field:List.of("duplicate","removed","emitter","data")){var f=new Fixture();f.funding("DEPOSIT");if(field.equals("duplicate"))((ObjectNode)f.logs.get(1)).put("logIndex","0x0");if(field.equals("removed"))((ObjectNode)f.logs.get(0)).put("removed",true);if(field.equals("emitter"))((ObjectNode)f.logs.get(0)).put("address",f.id.controller().address());if(field.equals("data"))((ObjectNode)f.logs.get(0)).put("data","0x");assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(f));}}
    @Test void changedHeaderReceiptOrTxBlockCannotBeConfirmed(){for(String field:List.of("reorg","receipt","txBlock","membership")){var f=new Fixture();if(field.equals("reorg"))f.reorg=true;if(field.equals("receipt"))f.receiptChanges=true;if(field.equals("txBlock"))f.tx.put("blockHash",h(999));if(field.equals("membership")){f.tx.put("transactionIndex","0x1");f.receipt.put("transactionIndex","0x1");((ObjectNode)f.logs.get(0)).put("transactionIndex","0x1");}assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(f));}}
    @Test void directFalseOrWrongStoredCalldataAndMissingEvidenceCannotConfirm(){var f=new Fixture();f.direct(false,ZERO);assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",assertThrows(CCustodyFailure.class,()->f.reader().inspect(f.owner,f.txHash,null)).code());var last=(ObjectNode)f.logs.get(f.logs.size()-1);var direct=(Direct)new CAbiCodec().decode(Target.CONTROLLER,f.tx.path("input").asText());var crypto=new CEip712Verifier();var encoded=new CAbiEventCodec().encode(f.id.controller().address(),new CUserIntentExecuted(direct.intent().operationId(),direct.intent().positionId(),f.owner,crypto.intentDigest(direct.intent(),f.id.chainId(),f.id.controller().address()),crypto.reportDigest(direct.report(),f.id.chainId(),f.id.rules().address()),ZERO,ZERO,false));last.put("data",encoded.data());assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(f));var mismatch=new Fixture();mismatch.direct(false,ZERO);mismatch.tx.put("input",mismatch.tx.path("input").asText()+"00");assertEquals("C_DIRECT_RECEIPT_REVIEW_REQUIRED",reject(mismatch));}
}
